-- Aprenda se Divertindo · 103 · Simulado 1 da Trilha Tribunais
-- Rode depois do 102-simulados-07-08-nov.sql. Cole tudo no SQL Editor e clique em Run.
-- Cria e publica o Simulado 1 da trilha Tribunais: abre no sábado, 07/11/2026, às 0h, e fecha no domingo, 08/11/2026, às 23h59.
-- 100 questões de A a E, estilo FCC, 4 horas de prova.
-- Português 15, Raciocínio Lógico 6, Informática 6, Constitucional 10, Administrativo 10, Civil 10, Processo Civil 10,
-- Penal 8, Processo Penal 8, Arquivologia 5, Gestão 4, Pessoa com Deficiência 3, Sustentabilidade 3, Inteligência Artificial 2.
-- Gabarito equilibrado: 20 questões com cada letra. Gabarito comentado na segunda, 09/11, às 0h.
-- Rodar de novo atualiza as questões, desde que ninguém tenha começado a prova.

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "O acesso à justiça não se esgota na possibilidade de ajuizar uma ação. De pouco adianta abrir as portas do tribunal se o processo demora tanto que, ao final, a decisão já não serve a ninguém. Uma sentença que chega tarde pode ser formalmente correta e, ainda assim, materialmente inútil. Por isso, a duração razoável do processo passou a figurar entre os direitos fundamentais, ao lado do contraditório e da ampla defesa.\n\nNão se trata, porém, de transformar a pressa em virtude. Um julgamento rápido que atropela as garantias das partes troca um problema por outro. O desafio do Judiciário é encontrar o ponto de equilíbrio: decidir em tempo útil sem abrir mão da qualidade da decisão. Ferramentas tecnológicas e métodos consensuais de solução de conflitos ajudam, mas não substituem a gestão cuidadosa de cada processo.", "enunciado": "Segundo o texto, uma sentença que chega tarde", "opcoes": ["pode ser correta na forma e, ainda assim, inútil na prática.", "é sempre nula, por violar a duração razoável do processo.", "é preferível a um julgamento rápido e cuidadoso.", "deve ser substituída por um acordo entre as partes do processo, sempre.", "revela, por si só, que o juiz desrespeitou o contraditório."], "gabarito": 0, "explicacao": "“Pode ser formalmente correta e, ainda assim, materialmente inútil.”"}, {"materia": "port", "texto_base": "O acesso à justiça não se esgota na possibilidade de ajuizar uma ação. De pouco adianta abrir as portas do tribunal se o processo demora tanto que, ao final, a decisão já não serve a ninguém. Uma sentença que chega tarde pode ser formalmente correta e, ainda assim, materialmente inútil. Por isso, a duração razoável do processo passou a figurar entre os direitos fundamentais, ao lado do contraditório e da ampla defesa.\n\nNão se trata, porém, de transformar a pressa em virtude. Um julgamento rápido que atropela as garantias das partes troca um problema por outro. O desafio do Judiciário é encontrar o ponto de equilíbrio: decidir em tempo útil sem abrir mão da qualidade da decisão. Ferramentas tecnológicas e métodos consensuais de solução de conflitos ajudam, mas não substituem a gestão cuidadosa de cada processo.", "enunciado": "No segundo parágrafo, o autor", "opcoes": ["defende que a pressa é a principal virtude do Judiciário moderno.", "sustenta que a qualidade da decisão depende só da tecnologia.", "afirma que os métodos consensuais resolvem todos os atrasos.", "adverte que a rapidez não pode sacrificar as garantias das partes.", "propõe trocar a gestão dos processos por ferramentas tecnológicas."], "gabarito": 3, "explicacao": "“Um julgamento rápido que atropela as garantias das partes troca um problema por outro.”"}, {"materia": "port", "texto_base": "O acesso à justiça não se esgota na possibilidade de ajuizar uma ação. De pouco adianta abrir as portas do tribunal se o processo demora tanto que, ao final, a decisão já não serve a ninguém. Uma sentença que chega tarde pode ser formalmente correta e, ainda assim, materialmente inútil. Por isso, a duração razoável do processo passou a figurar entre os direitos fundamentais, ao lado do contraditório e da ampla defesa.\n\nNão se trata, porém, de transformar a pressa em virtude. Um julgamento rápido que atropela as garantias das partes troca um problema por outro. O desafio do Judiciário é encontrar o ponto de equilíbrio: decidir em tempo útil sem abrir mão da qualidade da decisão. Ferramentas tecnológicas e métodos consensuais de solução de conflitos ajudam, mas não substituem a gestão cuidadosa de cada processo.", "enunciado": "No início do segundo parágrafo, a palavra “porém” estabelece relação de", "opcoes": ["condição para que haja acesso à justiça.", "oposição em relação à ideia anterior.", "adição de um novo exemplo ao argumento.", "conclusão do raciocínio do primeiro parágrafo.", "explicação da causa dos atrasos processuais."], "gabarito": 1, "explicacao": "Ressalva: a duração razoável não significa pressa."}, {"materia": "port", "texto_base": "O acesso à justiça não se esgota na possibilidade de ajuizar uma ação. De pouco adianta abrir as portas do tribunal se o processo demora tanto que, ao final, a decisão já não serve a ninguém. Uma sentença que chega tarde pode ser formalmente correta e, ainda assim, materialmente inútil. Por isso, a duração razoável do processo passou a figurar entre os direitos fundamentais, ao lado do contraditório e da ampla defesa.\n\nNão se trata, porém, de transformar a pressa em virtude. Um julgamento rápido que atropela as garantias das partes troca um problema por outro. O desafio do Judiciário é encontrar o ponto de equilíbrio: decidir em tempo útil sem abrir mão da qualidade da decisão. Ferramentas tecnológicas e métodos consensuais de solução de conflitos ajudam, mas não substituem a gestão cuidadosa de cada processo.", "enunciado": "Em “De pouco adianta abrir as portas do tribunal”, a expressão “abrir as portas do tribunal” é empregada em sentido", "opcoes": ["literal, referindo-se ao horário de funcionamento do fórum.", "hiperbólico, exagerando o número de ações ajuizadas.", "irônico, criticando a arquitetura dos prédios dos tribunais.", "técnico, indicando a distribuição da petição inicial.", "figurado, significando permitir o acesso ao Judiciário."], "gabarito": 4, "explicacao": "Metáfora para o direito de ação."}, {"materia": "port", "texto_base": "O acesso à justiça não se esgota na possibilidade de ajuizar uma ação. De pouco adianta abrir as portas do tribunal se o processo demora tanto que, ao final, a decisão já não serve a ninguém. Uma sentença que chega tarde pode ser formalmente correta e, ainda assim, materialmente inútil. Por isso, a duração razoável do processo passou a figurar entre os direitos fundamentais, ao lado do contraditório e da ampla defesa.\n\nNão se trata, porém, de transformar a pressa em virtude. Um julgamento rápido que atropela as garantias das partes troca um problema por outro. O desafio do Judiciário é encontrar o ponto de equilíbrio: decidir em tempo útil sem abrir mão da qualidade da decisão. Ferramentas tecnológicas e métodos consensuais de solução de conflitos ajudam, mas não substituem a gestão cuidadosa de cada processo.", "enunciado": "Em “se o processo demora tanto que, ao final, a decisão já não serve a ninguém”, a oração iniciada por “que” tem valor", "opcoes": ["consecutivo.", "causal.", "final.", "comparativo.", "concessivo."], "gabarito": 0, "explicacao": "“Tanto… que” introduz consequência."}, {"materia": "port", "texto_base": "O acesso à justiça não se esgota na possibilidade de ajuizar uma ação. De pouco adianta abrir as portas do tribunal se o processo demora tanto que, ao final, a decisão já não serve a ninguém. Uma sentença que chega tarde pode ser formalmente correta e, ainda assim, materialmente inútil. Por isso, a duração razoável do processo passou a figurar entre os direitos fundamentais, ao lado do contraditório e da ampla defesa.\n\nNão se trata, porém, de transformar a pressa em virtude. Um julgamento rápido que atropela as garantias das partes troca um problema por outro. O desafio do Judiciário é encontrar o ponto de equilíbrio: decidir em tempo útil sem abrir mão da qualidade da decisão. Ferramentas tecnológicas e métodos consensuais de solução de conflitos ajudam, mas não substituem a gestão cuidadosa de cada processo.", "enunciado": "Em “Não se trata, porém, de transformar a pressa em virtude”, o verbo fica na terceira pessoa do singular porque", "opcoes": ["há um sujeito oculto, que é o próprio autor do texto.", "concorda com o sujeito “pressa”, que está no singular, logo depois.", "o sujeito é indeterminado, e o “se” indica essa indeterminação.", "concorda com o sujeito “pressa”, que está no singular.", "o “se” é pronome apassivador e o sujeito é “transformar”."], "gabarito": 2, "explicacao": "“Tratar-se de” não admite sujeito; o verbo fica no singular."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase correta quanto à concordância nominal.", "opcoes": ["As provas e o laudo estavam anexas.", "Bastante pessoas compareceram à audiência.", "É necessário muita atenção nos prazos.", "Seguem incluso os documentos solicitados.", "Seguem inclusos os documentos solicitados."], "gabarito": 4, "explicacao": "“Incluso” concorda com “documentos”. Com sujeito composto de gêneros diferentes, usa-se o masculino; “bastante” (adjetivo) concorda; “É necessária muita atenção”."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase correta quanto à regência verbal.", "opcoes": ["Os advogados preferem acordo do que litígio.", "O juiz simpatizou-se com a tese da defesa.", "O oficial de justiça chegou ao fórum às 9h.", "A testemunha não se lembrou o nome do réu.", "O oficial de justiça chegou no fórum às 9h."], "gabarito": 2, "explicacao": "Verbos de movimento pedem “a”; “simpatizar” não é pronominal; “lembrar-se de”; “preferir algo a algo”."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a alternativa em que o emprego de “porquê”, “por que”, “porque” ou “por quê” está correto.", "opcoes": ["Ninguém explicou o porquê da decisão.", "Você recorreu da sentença porquê?", "O motivo porquê recorreu é desconhecido.", "Faltou à audiência por quê estava doente.", "O juiz não disse porque adiou a sessão."], "gabarito": 0, "explicacao": "“O porquê” é substantivo. Nas demais: “por que” (pergunta indireta e pronome relativo), “por quê” (fim de frase) e “porque” (causa)."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase que contém erro de grafia.", "opcoes": ["A rescisão do contrato foi homologada.", "O juiz homologou a cessão de crédito.", "A sessão foi suspensa por falta de quórum mínimo.", "A exceção de incompetência foi rejeitada.", "O réu teve a pretenção negada pelo tribunal."], "gabarito": 4, "explicacao": "Escreve-se “pretensão”."}, {"materia": "port", "texto_base": "", "enunciado": "Em “O juiz, cuja decisão foi reformada, recorreu ao CNJ”, o pronome “cuja” estabelece relação de", "opcoes": ["tempo entre as duas orações do período.", "lugar em que a decisão foi tomada.", "causa entre a reforma e o recurso.", "posse entre “juiz” e “decisão”.", "oposição entre o juiz e o CNJ."], "gabarito": 3, "explicacao": "“Cujo” é pronome relativo que indica posse."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase em que a vírgula foi empregada corretamente.", "opcoes": ["Senhor juiz, a defesa pede a palavra.", "O advogado, pediu a palavra ao juiz.", "A defesa e a acusação, apresentaram memoriais.", "Os autos foram, remetidos ao tribunal.", "O juiz decidiu, que a audiência seria adiada."], "gabarito": 0, "explicacao": "Isola-se o vocativo. Não se separa sujeito de verbo nem verbo de complemento."}, {"materia": "port", "texto_base": "", "enunciado": "Passando “O tribunal publicou o acórdão” para a voz passiva sintética, obtém-se:", "opcoes": ["O acórdão foi publicado pelo tribunal.", "Publicou-se o acórdão.", "Publicou-se o acórdão pelo tribunal.", "Publicaram-se o acórdão.", "O acórdão publicou-se a si mesmo."], "gabarito": 1, "explicacao": "Voz passiva sintética: verbo + “se” + sujeito, sem agente expresso."}, {"materia": "port", "texto_base": "", "enunciado": "Em “Era preciso que todos comparecessem”, a forma “comparecessem” está no", "opcoes": ["futuro do subjuntivo.", "pretérito mais-que-perfeito do indicativo.", "pretérito imperfeito do subjuntivo.", "pretérito imperfeito do indicativo.", "presente do subjuntivo."], "gabarito": 2, "explicacao": "Terminação -sse- caracteriza o imperfeito do subjuntivo."}, {"materia": "port", "texto_base": "", "enunciado": "A palavra “inconstitucionalidade” é formada por", "opcoes": ["derivação parassintética.", "derivação regressiva.", "prefixação e sufixação.", "composição por justaposição.", "composição por aglutinação."], "gabarito": 2, "explicacao": "in- + constitucional + -idade. Não é parassintética, pois “inconstitucional” existe sem o sufixo."}, {"materia": "rl", "texto_base": "", "enunciado": "A negação de “O juiz deferiu o pedido e marcou a audiência” é:", "opcoes": ["O juiz indeferiu o pedido e marcou a audiência.", "Se o juiz deferiu o pedido, então marcou a audiência.", "O juiz não deferiu o pedido e não marcou a audiência.", "O juiz deferiu o pedido ou marcou a audiência de instrução.", "O juiz não deferiu o pedido ou não marcou a audiência."], "gabarito": 4, "explicacao": "¬(P ∧ Q) ≡ ¬P ∨ ¬Q."}, {"materia": "rl", "texto_base": "", "enunciado": "Se “Nenhum servidor do fórum é advogado” e “Alguns advogados são professores”, conclui-se necessariamente que", "opcoes": ["todos os professores são advogados.", "nenhum advogado é professor.", "alguns professores não são servidores do fórum.", "nenhum professor é servidor do fórum.", "alguns servidores do fórum são professores universitários."], "gabarito": 2, "explicacao": "Os professores que são advogados não podem ser servidores do fórum."}, {"materia": "rl", "texto_base": "", "enunciado": "Um processo pode ir para uma de 3 varas e, em cada vara, para um de 4 juízes. O número de formas de escolher vara e juiz é", "opcoes": ["7.", "12.", "81.", "64.", "24."], "gabarito": 1, "explicacao": "Princípio multiplicativo: 3 × 4."}, {"materia": "rl", "texto_base": "", "enunciado": "Numa vara, 60% dos processos são cíveis e, destes, 25% estão parados. Os processos cíveis parados representam, do total,", "opcoes": ["25%.", "85%.", "15%.", "35%.", "45%."], "gabarito": 2, "explicacao": "0,60 × 0,25 = 0,15."}, {"materia": "rl", "texto_base": "", "enunciado": "Um servidor digita 40 páginas em 5 horas. No mesmo ritmo, em 8 horas digitará", "opcoes": ["64 páginas.", "72 páginas.", "56 páginas.", "48 páginas.", "60 páginas."], "gabarito": 0, "explicacao": "8 páginas por hora × 8."}, {"materia": "rl", "texto_base": "", "enunciado": "Numa fila, Ana está à frente de Bruno, Carla está atrás de Bruno e Davi está à frente de Ana. Quem ocupa o terceiro lugar?", "opcoes": ["Bruno.", "Ana.", "Carla.", "Não é possível saber.", "Davi."], "gabarito": 0, "explicacao": "Ordem: Davi, Ana, Bruno, Carla."}, {"materia": "inf", "texto_base": "", "enunciado": "No Microsoft Word em português, o atalho Ctrl + B serve para", "opcoes": ["abrir um documento.", "imprimir o documento.", "localizar uma palavra.", "salvar o documento.", "aplicar negrito ao texto."], "gabarito": 3, "explicacao": "No Word em português, negrito é Ctrl + N."}, {"materia": "inf", "texto_base": "", "enunciado": "No Windows, o atalho Win + D serve para", "opcoes": ["bloquear o computador.", "abrir o Explorador de Arquivos.", "duplicar a janela ativa.", "mostrar a área de trabalho.", "abrir as Configurações."], "gabarito": 3, "explicacao": "Win + E abre o Explorador; Win + L bloqueia; Win + I abre as Configurações."}, {"materia": "inf", "texto_base": "", "enunciado": "No processo eletrônico, a assinatura digital com certificado ICP-Brasil garante principalmente", "opcoes": ["a gratuidade da tramitação do processo.", "o sigilo absoluto do conteúdo enviado.", "a velocidade no envio da petição.", "a compactação dos arquivos anexados.", "a autoria e a integridade do documento."], "gabarito": 4, "explicacao": "Não garante, por si só, o sigilo."}, {"materia": "inf", "texto_base": "", "enunciado": "Guardar uma cópia de segurança em local físico diferente do original serve, sobretudo, para", "opcoes": ["acelerar a recuperação de arquivos apagados por engano.", "acelerar a recuperação de arquivos apagados por engano no setor.", "reduzir o espaço ocupado pelos arquivos no servidor.", "evitar a perda total em caso de incêndio ou desastre.", "dispensar o uso de senhas nos arquivos copiados."], "gabarito": 3, "explicacao": "Boa prática de continuidade do serviço."}, {"materia": "inf", "texto_base": "", "enunciado": "Numa planilha, a função =MÁXIMO(A1:A5) retorna", "opcoes": ["a média dos valores do intervalo.", "a quantidade de células preenchidas.", "o maior valor do intervalo.", "o último valor digitado no intervalo.", "a soma dos valores do intervalo."], "gabarito": 2, "explicacao": "MÁXIMO devolve o maior número."}, {"materia": "inf", "texto_base": "", "enunciado": "O protocolo que permite ler e-mails mantendo as mensagens sincronizadas no servidor é o", "opcoes": ["POP3.", "SMTP.", "HTTP.", "FTP.", "IMAP."], "gabarito": 4, "explicacao": "O POP3 costuma baixar e retirar as mensagens do servidor; o SMTP envia."}, {"materia": "const", "texto_base": "", "enunciado": "Compete ao Conselho Nacional de Justiça, entre outras atribuições,", "opcoes": ["exercer função jurisdicional sobre os tribunais superiores.", "controlar a atuação administrativa e financeira do Judiciário.", "fiscalizar o STF, inclusive o mérito de suas decisões.", "nomear os ministros do Supremo Tribunal Federal.", "julgar recursos contra sentenças dos juízes de primeiro grau do país."], "gabarito": 1, "explicacao": "Art. 103-B, § 4º, da CF. O CNJ não tem competência sobre o STF nem função jurisdicional."}, {"materia": "const", "texto_base": "", "enunciado": "A aposentadoria compulsória dos magistrados ocorre aos", "opcoes": ["72 anos.", "65 anos.", "70 anos.", "75 anos.", "80 anos."], "gabarito": 3, "explicacao": "Art. 40, § 1º, II, da CF e LC 152/2015."}, {"materia": "const", "texto_base": "", "enunciado": "O quinto constitucional aplica-se, entre outros, aos", "opcoes": ["Tribunais de Contas dos estados e da União.", "Supremo Tribunal Federal e Tribunal Superior Eleitoral.", "juizados especiais cíveis e criminais.", "Tribunais Regionais Federais e Tribunais de Justiça.", "juízos de primeiro grau das justiças estaduais."], "gabarito": 3, "explicacao": "Art. 94 da CF."}, {"materia": "const", "texto_base": "", "enunciado": "No primeiro grau, o juiz adquire a vitaliciedade após", "opcoes": ["2 anos de exercício.", "5 anos de exercício.", "1 ano de exercício.", "3 anos de exercício.", "a posse no cargo."], "gabarito": 0, "explicacao": "Art. 95, I, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "Cabe recurso especial ao STJ contra decisão de TRF ou TJ, em única ou última instância, que", "opcoes": ["decidir crime político em primeira instância.", "contrariar dispositivo da Constituição Federal.", "tratar de matéria trabalhista entre empregado e patrão.", "julgar válida lei local contestada em face da Constituição.", "contrariar tratado ou lei federal, ou negar-lhes vigência."], "gabarito": 4, "explicacao": "Art. 105, III, a, da CF. As duas primeiras hipóteses são de recurso extraordinário."}, {"materia": "const", "texto_base": "", "enunciado": "Para que o recurso extraordinário seja admitido, o recorrente deve demonstrar a", "opcoes": ["existência de prova nova obtida após a sentença.", "urgência na proteção do direito alegado.", "divergência entre tribunais sobre lei federal.", "repercussão geral da questão constitucional.", "ofensa a súmula do Superior Tribunal de Justiça."], "gabarito": 3, "explicacao": "Art. 102, § 3º, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "A súmula vinculante é aprovada pelo STF por decisão de", "opcoes": ["maioria simples dos presentes.", "três quintos dos seus membros.", "unanimidade dos seus membros.", "maioria absoluta dos seus membros.", "dois terços dos seus membros."], "gabarito": 4, "explicacao": "Art. 103-A da CF."}, {"materia": "const", "texto_base": "", "enunciado": "Contra ato administrativo que contrarie súmula vinculante cabe", "opcoes": ["arguição de descumprimento de preceito fundamental.", "reclamação ao STF.", "recurso especial ao STJ.", "mandado de injunção.", "ação rescisória."], "gabarito": 1, "explicacao": "Art. 103-A, § 3º, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "O mandado de injunção é cabível quando", "opcoes": ["alguém sofrer ameaça de violência ou coação em sua liberdade de locomoção.", "um ato lesivo ao patrimônio público precisar ser anulado pelo cidadão.", "alguém sofrer ameaça de violência ou coação ilegal em sua liberdade de locomoção.", "a falta de norma regulamentadora inviabiliza direito previsto na Constituição.", "houver lesão a direito líquido e certo por ato de autoridade pública."], "gabarito": 3, "explicacao": "Art. 5º, LXXI, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "Entre as vedações aos juízes previstas na Constituição está", "opcoes": ["exercer uma função de magistério, junto com a judicatura.", "dedicar-se a atividade político-partidária.", "publicar livros sobre temas jurídicos.", "ministrar palestras em universidades.", "participar de congressos acadêmicos."], "gabarito": 1, "explicacao": "Art. 95, parágrafo único, III, da CF."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.112/1990, o servidor em estágio probatório pode exercer cargo em comissão?", "opcoes": ["Sim, em qualquer órgão de qualquer dos Poderes.", "Sim, no órgão ou entidade em que está lotado.", "Somente após 2 anos de efetivo exercício.", "Somente com autorização expressa do Congresso.", "Não, em nenhuma hipótese durante o estágio."], "gabarito": 1, "explicacao": "Art. 20, § 3º, da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.112/1990, as férias podem ser acumuladas até o máximo de", "opcoes": ["dois períodos, por necessidade do serviço.", "quatro períodos, se o chefe autorizar.", "um período, sem nenhuma exceção.", "três períodos, a pedido do próprio servidor.", "cinco períodos, ao longo da carreira."], "gabarito": 0, "explicacao": "Art. 77 da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.112/1990, a licença para tratar de interesses particulares pode durar até", "opcoes": ["2 anos, com remuneração integral.", "6 meses, prorrogáveis por igual período.", "5 anos, sem remuneração.", "1 ano, com metade da remuneração.", "3 anos consecutivos, sem remuneração."], "gabarito": 4, "explicacao": "Art. 91 da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "O servidor que acumula cargos ilegalmente e, notificado, não faz a opção no prazo está sujeito a", "opcoes": ["demissão, após procedimento sumário.", "advertência por escrito, apenas.", "remoção de ofício para outro órgão.", "exoneração a pedido, sem processo.", "suspensão de 30 dias, sem salário."], "gabarito": 0, "explicacao": "Art. 133 da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Constituição, havendo compatibilidade de horários, é permitida a acumulação remunerada de", "opcoes": ["dois cargos técnicos quaisquer, no mesmo órgão.", "três cargos de professor, em redes diferentes.", "um de professor com outro técnico ou científico.", "um cargo de analista com um de técnico judiciário.", "dois cargos de juiz, em comarcas vizinhas."], "gabarito": 2, "explicacao": "Art. 37, XVI, b, da CF."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.112/1990, a responsabilidade administrativa do servidor é afastada no caso de", "opcoes": ["absolvição criminal por falta de provas suficientes.", "arquivamento do inquérito policial instaurado sobre o mesmo fato.", "extinção da punibilidade pela prescrição penal.", "transação penal homologada no juizado especial.", "absolvição criminal que negue o fato ou sua autoria."], "gabarito": 4, "explicacao": "Art. 126 da Lei 8.112/1990."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 9.784/1999, é direito do administrado", "opcoes": ["ser dispensado de provar o que alega no processo.", "exigir que o processo seja decidido em 24 horas.", "ter vista dos autos e obter cópias dos documentos.", "recusar qualquer intimação do órgão.", "escolher a autoridade que decidirá o processo."], "gabarito": 2, "explicacao": "Art. 3º, II, da Lei 9.784/1999."}, {"materia": "adm", "texto_base": "", "enunciado": "Na Lei 14.133/2021, o agente de contratação é designado entre", "opcoes": ["servidores efetivos ou empregados públicos de quadros permanentes.", "qualquer cidadão com formação jurídica e experiência.", "membros do Tribunal de Contas da respectiva esfera.", "servidores comissionados sem vínculo, exclusivamente.", "pessoas indicadas pelos próprios licitantes interessados no contrato."], "gabarito": 0, "explicacao": "Art. 8º da Lei 14.133/2021."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei de Acesso à Informação, não sendo possível o acesso imediato, o órgão deve responder em até", "opcoes": ["15 dias, prorrogáveis por mais 15.", "10 dias, prorrogáveis por mais 5.", "20 dias, prorrogáveis por mais 10.", "5 dias úteis, sem prorrogação.", "30 dias, sem prorrogação."], "gabarito": 2, "explicacao": "Art. 11, §§ 1º e 2º, da Lei 12.527/2011."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei de Acesso à Informação, a informação ultrassecreta pode ter o acesso restrito por até", "opcoes": ["5 anos.", "15 anos.", "100 anos.", "25 anos.", "50 anos."], "gabarito": 3, "explicacao": "Art. 24, § 1º, da Lei 12.527/2011. Secreta: 15; reservada: 5."}, {"materia": "civ", "texto_base": "", "enunciado": "Pelo Código Civil, a personalidade civil da pessoa começa", "opcoes": ["do registro de nascimento no cartório civil.", "da concepção, com todos os direitos de quem já nasceu com vida.", "do nascimento com vida, protegidos os direitos do nascituro.", "aos 18 anos, com a maioridade civil plena.", "aos 16 anos, com a obtenção do título de eleitor."], "gabarito": 2, "explicacao": "Art. 2º do Código Civil."}, {"materia": "civ", "texto_base": "", "enunciado": "Após a Lei 13.146/2015, são absolutamente incapazes", "opcoes": ["os que não podem exprimir sua vontade.", "os menores de 16 anos.", "as pessoas com deficiência intelectual.", "os menores de 18 anos.", "os ébrios habituais."], "gabarito": 1, "explicacao": "Art. 3º do Código Civil."}, {"materia": "civ", "texto_base": "", "enunciado": "A incapacidade do menor cessa antes dos 18 anos, entre outros casos, pelo", "opcoes": ["vestibular.", "noivado.", "ingresso no ensino médio.", "alistamento militar.", "casamento."], "gabarito": 4, "explicacao": "Art. 5º, parágrafo único, II, do Código Civil."}, {"materia": "civ", "texto_base": "", "enunciado": "Quando a lei não fixa prazo menor, a prescrição ocorre em", "opcoes": ["20 anos.", "5 anos.", "10 anos.", "15 anos.", "3 anos."], "gabarito": 2, "explicacao": "Art. 205 do Código Civil."}, {"materia": "civ", "texto_base": "", "enunciado": "Prescreve em 3 anos a pretensão de", "opcoes": ["cobrar dívida líquida de instrumento público.", "haver prestações alimentares.", "haver o pagamento de honorários periciais.", "segurado contra o segurador.", "reparação civil."], "gabarito": 4, "explicacao": "Art. 206, § 3º, V. Alimentos: 2 anos; dívida líquida: 5; segurado: 1; honorários: 1 (art. 206, § 1º, III)."}, {"materia": "civ", "texto_base": "", "enunciado": "O negócio jurídico celebrado por erro substancial é", "opcoes": ["sempre válido.", "ineficaz.", "anulável.", "inexistente.", "nulo."], "gabarito": 2, "explicacao": "Arts. 138 e 171, II, do Código Civil."}, {"materia": "civ", "texto_base": "", "enunciado": "O negócio jurídico simulado é", "opcoes": ["ineficaz.", "nulo.", "anulável.", "válido.", "inexistente."], "gabarito": 1, "explicacao": "Art. 167 do Código Civil."}, {"materia": "civ", "texto_base": "", "enunciado": "O prazo de decadência para anular negócio jurídico por coação é de 4 anos, contado", "opcoes": ["do dia em que cessar a coação.", "da citação do réu na ação.", "da data em que o negócio foi celebrado.", "do registro do contrato em cartório.", "do dia em que se conheceu o vício."], "gabarito": 0, "explicacao": "Art. 178, I, do Código Civil."}, {"materia": "civ", "texto_base": "", "enunciado": "Pelo Código Civil, o dono ou detentor do animal ressarcirá o dano por este causado", "opcoes": ["se não provar culpa da vítima ou força maior.", "só se houver condenação criminal antes.", "só se ficar provada a culpa do dono.", "nunca, se o animal estava solto na rua sem dono.", "apenas se o animal for de raça perigosa."], "gabarito": 0, "explicacao": "Art. 936 do Código Civil."}, {"materia": "civ", "texto_base": "", "enunciado": "O domicílio da pessoa natural é", "opcoes": ["o endereço que consta na carteira de identidade.", "o município onde ela vota nas eleições.", "o endereço da empresa onde ela trabalha atualmente.", "o lugar onde ela reside com ânimo definitivo.", "o lugar onde ela nasceu e foi registrada."], "gabarito": 3, "explicacao": "Art. 70 do Código Civil."}, {"materia": "pciv", "texto_base": "", "enunciado": "Pelo CPC, os prazos processuais em dias contam-se", "opcoes": ["em dias corridos.", "em horas.", "somente em dias úteis.", "em dias úteis só para a Fazenda.", "em semanas."], "gabarito": 2, "explicacao": "Art. 219 do CPC."}, {"materia": "pciv", "texto_base": "", "enunciado": "No procedimento comum, o prazo para contestar é de", "opcoes": ["10 dias úteis.", "5 dias úteis.", "30 dias úteis.", "15 dias úteis.", "20 dias úteis."], "gabarito": 3, "explicacao": "Art. 335 do CPC."}, {"materia": "pciv", "texto_base": "", "enunciado": "A Fazenda Pública, o Ministério Público e a Defensoria Pública têm, em regra, prazo", "opcoes": ["igual ao das demais partes do processo.", "em dobro só para recorrer.", "em dobro para todas as suas manifestações.", "em triplo para recorrer de sentenças.", "em quádruplo para contestar e em dobro para recorrer."], "gabarito": 2, "explicacao": "Arts. 180, 183 e 186 do CPC."}, {"materia": "pciv", "texto_base": "", "enunciado": "Em regra, a revelia faz", "opcoes": ["suspender o processo por 30 dias.", "presumir verdadeiros os fatos alegados pelo autor.", "extinguir o processo sem resolução do mérito, de ofício.", "anular a citação feita ao réu.", "condenar o autor ao pagamento das custas."], "gabarito": 1, "explicacao": "Art. 344 do CPC, com as exceções do art. 345."}, {"materia": "pciv", "texto_base": "", "enunciado": "No CPC, o prazo para interpor apelação é de", "opcoes": ["5 dias.", "8 dias.", "30 dias.", "15 dias.", "10 dias."], "gabarito": 3, "explicacao": "Art. 1.003, § 5º, do CPC."}, {"materia": "pciv", "texto_base": "", "enunciado": "No CPC, os embargos de declaração devem ser opostos em", "opcoes": ["8 dias.", "5 dias.", "3 dias.", "10 dias.", "15 dias."], "gabarito": 1, "explicacao": "Art. 1.023 do CPC."}, {"materia": "pciv", "texto_base": "", "enunciado": "Contra decisão interlocutória sobre tutela provisória cabe", "opcoes": ["apelação, ao final do processo.", "agravo de instrumento.", "agravo interno.", "recurso especial.", "recurso ordinário."], "gabarito": 1, "explicacao": "Art. 1.015, I, do CPC."}, {"materia": "pciv", "texto_base": "", "enunciado": "Pelo CPC, a tutela provisória pode fundamentar-se em", "opcoes": ["urgência ou evidência.", "pedido do Ministério Público.", "conveniência do juiz.", "evidência, apenas.", "urgência, apenas."], "gabarito": 0, "explicacao": "Art. 294 do CPC."}, {"materia": "pciv", "texto_base": "", "enunciado": "A audiência de conciliação ou mediação do art. 334 do CPC não será realizada se", "opcoes": ["apenas o autor manifestar desinteresse na petição.", "o réu deixar de ser citado no prazo de 30 dias.", "o juiz preferir julgar logo o mérito.", "as duas partes manifestarem desinteresse no acordo.", "o processo tramitar em meio físico."], "gabarito": 3, "explicacao": "Art. 334, § 4º, I, do CPC."}, {"materia": "pciv", "texto_base": "", "enunciado": "No incidente de resolução de demandas repetitivas (IRDR), a tese jurídica fixada pelo tribunal", "opcoes": ["tem efeito apenas consultivo, sem obrigar ninguém.", "só vincula os juízes que concordarem expressamente com ela.", "vale apenas para as partes do processo que originou o incidente.", "só se aplica aos processos ajuizados depois do julgamento.", "aplica-se aos processos que tratem da mesma questão de direito."], "gabarito": 4, "explicacao": "Art. 985 do CPC."}, {"materia": "pen", "texto_base": "", "enunciado": "Usar de violência ou grave ameaça contra testemunha, para favorecer interesse próprio em processo judicial, é crime de", "opcoes": ["ameaça.", "coação no curso do processo.", "fraude processual.", "favorecimento pessoal.", "constrangimento ilegal qualificado."], "gabarito": 1, "explicacao": "Art. 344 do CP."}, {"materia": "pen", "texto_base": "", "enunciado": "O servidor que revela fato que conheceu em razão do cargo e que deveria permanecer em segredo comete", "opcoes": ["condescendência criminosa.", "prevaricação.", "advocacia administrativa qualificada.", "peculato.", "violação de sigilo funcional."], "gabarito": 4, "explicacao": "Art. 325 do CP."}, {"materia": "pen", "texto_base": "", "enunciado": "Patrocinar interesse privado perante a Administração, valendo-se da qualidade de servidor, é crime de", "opcoes": ["corrupção passiva.", "prevaricação qualificada.", "exploração de prestígio.", "tráfico de influência.", "advocacia administrativa."], "gabarito": 4, "explicacao": "Art. 321 do CP."}, {"materia": "pen", "texto_base": "", "enunciado": "O chefe que, por indulgência, deixa de responsabilizar subordinado que cometeu infração no exercício do cargo comete", "opcoes": ["advocacia administrativa simples.", "condescendência criminosa.", "prevaricação.", "favorecimento pessoal.", "omissão de socorro."], "gabarito": 1, "explicacao": "Art. 320 do CP."}, {"materia": "pen", "texto_base": "", "enunciado": "Comete exercício arbitrário das próprias razões quem", "opcoes": ["cobra dívida pelos meios legais, com ação judicial proposta no juízo competente.", "faz justiça pelas próprias mãos para satisfazer pretensão legítima ou não.", "se recusa a cumprir ordem judicial de pagamento de pensão alimentícia.", "oferece vantagem ao juiz para obter uma decisão favorável no processo.", "altera o local do crime para enganar o perito ou o juiz do caso."], "gabarito": 1, "explicacao": "Art. 345 do CP."}, {"materia": "pen", "texto_base": "", "enunciado": "Para o Código Penal, considera-se funcionário público quem", "opcoes": ["foi aprovado em concurso e já cumpriu o estágio probatório no cargo.", "recebe remuneração dos cofres públicos, com vínculo efetivo e permanente.", "ocupa cargo efetivo, depois de aprovado em concurso público e empossado.", "tem estabilidade no serviço público, adquirida após três anos de efetivo exercício.", "exerce cargo, emprego ou função pública, mesmo transitoriamente ou sem salário."], "gabarito": 4, "explicacao": "Art. 327 do CP."}, {"materia": "pen", "texto_base": "", "enunciado": "Inserir declaração falsa em documento verdadeiro, para alterar a verdade sobre fato juridicamente relevante, é crime de", "opcoes": ["falsidade ideológica.", "uso de documento falso.", "fraude processual.", "falsa identidade.", "falsificação de documento público."], "gabarito": 0, "explicacao": "Art. 299 do CP."}, {"materia": "pen", "texto_base": "", "enunciado": "Apresentar em juízo documento que sabe ser falso é crime de", "opcoes": ["estelionato.", "falsa identidade.", "uso de documento falso.", "fraude processual.", "falsidade ideológica simples."], "gabarito": 2, "explicacao": "Art. 304 do CP."}, {"materia": "ppen", "texto_base": "", "enunciado": "Nos crimes comuns, o desembargador do Tribunal de Justiça é julgado pelo", "opcoes": ["próprio Tribunal de Justiça, em plenário.", "Tribunal Regional Federal.", "juiz de primeiro grau.", "Supremo Tribunal Federal.", "Superior Tribunal de Justiça."], "gabarito": 4, "explicacao": "Art. 105, I, a, da CF."}, {"materia": "ppen", "texto_base": "", "enunciado": "Na ação penal exclusivamente privada, o querelante pode oferecer a queixa no foro do domicílio do réu, ainda que conhecido o lugar da infração?", "opcoes": ["Sim, à escolha do querelante.", "Só nos crimes de menor potencial ofensivo.", "Só se o juiz autorizar previamente.", "Não, deve ser sempre no lugar da infração.", "Só se o réu concordar expressamente."], "gabarito": 0, "explicacao": "Art. 73 do CPP."}, {"materia": "ppen", "texto_base": "", "enunciado": "O habeas corpus contra ato de juiz de primeiro grau é julgado pelo", "opcoes": ["próprio juiz que praticou o ato impugnado.", "tribunal a que o juiz está vinculado.", "Supremo Tribunal Federal.", "Conselho Nacional de Justiça.", "Superior Tribunal de Justiça."], "gabarito": 1, "explicacao": "Ex.: ato de juiz estadual, pelo Tribunal de Justiça."}, {"materia": "ppen", "texto_base": "", "enunciado": "Pelo CPP, a citação do réu preso deve ser feita", "opcoes": ["por hora certa.", "por carta registrada.", "na pessoa do advogado.", "por edital.", "pessoalmente."], "gabarito": 4, "explicacao": "Art. 360 do CPP."}, {"materia": "ppen", "texto_base": "", "enunciado": "As nulidades relativas que não forem arguidas no momento oportuno ficam sujeitas à", "opcoes": ["renúncia tácita da acusação.", "prescrição.", "perempção.", "preclusão.", "decadência."], "gabarito": 3, "explicacao": "Art. 572 do CPP."}, {"materia": "ppen", "texto_base": "", "enunciado": "No processo penal, o prazo para pedir ao juiz que esclareça obscuridade ou omissão da sentença (embargos de declaração) é de", "opcoes": ["2 dias.", "5 dias.", "3 dias.", "15 dias.", "10 dias."], "gabarito": 0, "explicacao": "Art. 382 do CPP."}, {"materia": "ppen", "texto_base": "", "enunciado": "Ocorre emendatio libelli quando o juiz", "opcoes": ["reconhece fato novo não descrito na denúncia e abre vista ao Ministério Público.", "anula o processo desde o recebimento da denúncia, por vício de citação.", "rejeita a denúncia por falta de justa causa para a ação penal.", "dá ao fato definição jurídica diversa, sem modificar sua descrição na denúncia.", "absolve o réu por não existir prova suficiente para a condenação."], "gabarito": 3, "explicacao": "Art. 383 do CPP. A outra hipótese é a mutatio libelli (art. 384)."}, {"materia": "ppen", "texto_base": "", "enunciado": "Na mutatio libelli, encerrada a instrução e surgindo prova de elemento não contido na acusação, é necessário", "opcoes": ["que a vítima ofereça nova queixa-crime em 6 meses.", "que o juiz condene o réu pelo novo fato, de ofício.", "o aditamento da denúncia pelo Ministério Público.", "que o réu seja ouvido apenas por escrito, sem audiência.", "que o processo seja extinto sem julgamento do mérito."], "gabarito": 2, "explicacao": "Art. 384 do CPP."}, {"materia": "arq", "texto_base": "", "enunciado": "A teoria das três idades divide os arquivos em", "opcoes": ["corrente, intermediário e permanente.", "ativo, semiativo, passivo e histórico.", "setorial, central e geral.", "público, privado e misto.", "físico, digital e híbrido."], "gabarito": 0, "explicacao": "Conforme a frequência de uso e o valor dos documentos."}, {"materia": "arq", "texto_base": "", "enunciado": "A tabela de temporalidade de documentos define", "opcoes": ["o tipo de papel usado em cada documento oficial.", "o número de cópias que cada setor deve manter.", "a ordem alfabética de arquivamento das pastas.", "os prazos de guarda e a destinação dos documentos.", "o grau de sigilo de cada informação do órgão."], "gabarito": 3, "explicacao": "Instrumento de avaliação e destinação."}, {"materia": "arq", "texto_base": "", "enunciado": "O arquivo intermediário guarda documentos que", "opcoes": ["aguardam a destinação final e têm uso pouco frequente.", "têm valor histórico e devem ser guardados para sempre.", "ainda não foram registrados no protocolo do órgão.", "já foram eliminados após o prazo de guarda.", "são consultados todos os dias pelos setores de origem."], "gabarito": 0, "explicacao": "Fase entre o arquivo corrente e a destinação (eliminação ou guarda permanente)."}, {"materia": "arq", "texto_base": "", "enunciado": "O princípio da proveniência determina que", "opcoes": ["os documentos digitais fiquem separados dos documentos em papel.", "documentos de uma mesma origem não se misturem aos de outra.", "os documentos sejam ordenados pela data de chegada ao arquivo.", "os documentos sejam agrupados apenas pelo assunto tratado.", "os documentos mais consultados fiquem sempre mais à mão."], "gabarito": 1, "explicacao": "Também chamado de princípio do respeito aos fundos."}, {"materia": "arq", "texto_base": "", "enunciado": "A eliminação de documentos públicos depende de", "opcoes": ["aprovação da comissão de avaliação, sem outra autorização.", "pedido do cidadão interessado nos documentos.", "autorização da instituição arquivística pública competente.", "parecer do Tribunal de Contas da respectiva esfera.", "simples decisão do chefe do setor que os produziu."], "gabarito": 2, "explicacao": "Art. 9º da Lei 8.159/1991."}, {"materia": "gest", "texto_base": "", "enunciado": "A matriz SWOT analisa", "opcoes": ["forças, fraquezas, oportunidades e ameaças.", "planejamento, execução, controle e ação.", "custos, receitas, lucros e perdas.", "metas, prazos, recursos e resultados.", "metas, prazos, recursos humanos e resultados."], "gabarito": 0, "explicacao": "Forças e fraquezas são internas; oportunidades e ameaças, externas."}, {"materia": "gest", "texto_base": "", "enunciado": "O ciclo PDCA corresponde às etapas de", "opcoes": ["prever, decidir, controlar e avaliar.", "planejar, executar, verificar e agir.", "planejar, dirigir, coordenar e arquivar.", "propor, delegar, cobrar e aprovar.", "pesquisar, definir, criar e aprovar."], "gabarito": 1, "explicacao": "Plan, Do, Check, Act."}, {"materia": "gest", "texto_base": "", "enunciado": "Na gestão por competências, a sigla CHA significa", "opcoes": ["cargos, horários e atribuições.", "competência, habilitação, aptidão e avaliação.", "conhecimentos, habilidades e atitudes.", "capacitação, histórico e avaliação.", "controle, hierarquia e autoridade."], "gabarito": 2, "explicacao": "Dimensões da competência profissional."}, {"materia": "gest", "texto_base": "", "enunciado": "No Balanced Scorecard, as quatro perspectivas são", "opcoes": ["eficiência, eficácia, efetividade e economicidade da gestão.", "financeira, clientes, processos internos e aprendizado.", "planejar, executar, verificar e agir sobre os resultados.", "estratégica, tática, operacional e administrativa da empresa.", "forças, fraquezas, oportunidades e ameaças do ambiente."], "gabarito": 1, "explicacao": "Kaplan e Norton."}, {"materia": "pcd", "texto_base": "", "enunciado": "Pela Lei Brasileira de Inclusão, a recusa de adaptações razoáveis configura", "opcoes": ["conduta permitida, se houver custo para a empresa.", "discriminação em razão da deficiência.", "simples falta administrativa, sem efeito.", "infração apenas ética, sem consequência legal.", "exercício regular de um direito do empregador."], "gabarito": 1, "explicacao": "Art. 4º, § 1º, da Lei 13.146/2015."}, {"materia": "pcd", "texto_base": "", "enunciado": "Pela LBI, nos processos judiciais em que for parte ou interessada, a pessoa com deficiência tem", "opcoes": ["dispensa do pagamento de qualquer valor em qualquer ação.", "direito a escolher o juiz que julgará o seu processo.", "isenção de comparecer às audiências em qualquer caso.", "prioridade na tramitação e nos atos e diligências.", "prazo em quádruplo para todas as suas manifestações."], "gabarito": 3, "explicacao": "Art. 9º, VII, da Lei 13.146/2015."}, {"materia": "pcd", "texto_base": "", "enunciado": "Pela LBI, a deficiência não afeta a plena capacidade civil da pessoa, inclusive para", "opcoes": ["isentar-se de qualquer responsabilidade civil.", "dispensar o voto obrigatório nas eleições.", "casar-se e constituir união estável.", "obter a aposentadoria antes dos 40 anos.", "exercer qualquer cargo sem concurso público."], "gabarito": 2, "explicacao": "Art. 6º, I, da Lei 13.146/2015."}, {"materia": "ia", "texto_base": "", "enunciado": "No uso de inteligência artificial generativa para minutar textos no Judiciário, uma boa prática essencial é", "opcoes": ["publicar o texto gerado sem leitura, para ganhar tempo.", "atribuir à ferramenta a autoria formal da decisão.", "inserir dados sigilosos das partes em qualquer ferramenta.", "revisão humana, com responsabilidade de quem assina.", "dispensar a fundamentação, já que a IA a dispensa."], "gabarito": 3, "explicacao": "A decisão continua sendo de responsabilidade humana."}, {"materia": "ia", "texto_base": "", "enunciado": "O viés algorítmico ocorre quando", "opcoes": ["o usuário digita comandos incompletos e recebe uma resposta curta.", "o computador desliga durante o processamento de um arquivo grande.", "o sistema exige internet de alta velocidade para funcionar bem.", "o sistema reproduz distorções dos dados usados no treino.", "o programa é mais rápido do que o servidor humano na mesma tarefa."], "gabarito": 3, "explicacao": "Pode gerar decisões discriminatórias."}, {"materia": "sust", "texto_base": "", "enunciado": "A Agenda 2030 da ONU reúne", "opcoes": ["20 objetivos ambientais obrigatórios.", "8 Objetivos de Desenvolvimento do Milênio.", "10 Objetivos de Desenvolvimento Sustentável.", "12 metas globais de combate à pobreza.", "17 Objetivos de Desenvolvimento Sustentável."], "gabarito": 4, "explicacao": "Os ODS foram adotados em 2015."}, {"materia": "sust", "texto_base": "", "enunciado": "O ODS 16 da Agenda 2030 trata de", "opcoes": ["redução das desigualdades.", "trabalho decente e crescimento econômico.", "parcerias e meios de implementação.", "cidades e comunidades sustentáveis.", "paz, justiça e instituições eficazes."], "gabarito": 4, "explicacao": "É o ODS mais ligado ao Judiciário."}, {"materia": "sust", "texto_base": "", "enunciado": "A Política Nacional de Resíduos Sólidos foi instituída pela Lei", "opcoes": ["12.305/2010.", "11.445/2007.", "14.026/2020.", "6.938/1981.", "9.605/1998."], "gabarito": 0, "explicacao": "A 9.605 é a de crimes ambientais; a 6.938, a Política Nacional do Meio Ambiente."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('tribunais', date '2026-11-08', 'Simulado 1 · Tribunais', 'FCC', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data - 1 as abre_sabado, s.data as fecha_domingo, s.titulo, s.estilo, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.data >= date '2026-11-08'
 group by s.id order by s.data, s.trilha;
